"""Record scoped pursuit decisions; retain all previous records and source identities."""
import json,datetime
from pathlib import Path
root=Path(__file__).resolve().parent
pkg=root.parent/'full-catalogue-v4/Demuxe_All_Items_Screening_v4'
prior={d['key']:d for d in map(json.loads,(pkg/'state/decisions.jsonl').read_text().splitlines())}
latest={d['key']:d for d in map(json.loads,(root/'completion.jsonl').read_text().splitlines())}
def put(prefix,state,evidence,reason,level='COMPONENT_TEST'):
 matches=[k for k in prior if k.startswith(prefix)]
 assert len(matches)==1,(prefix,matches)
 key=matches[0];paths=evidence if isinstance(evidence,list) else [evidence]
 assert all((root/p).is_file() for p in paths),paths
 record=dict(key=key,state=state,evidence=paths,reason=reason,evidence_level=level,recorded_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat())
 with (root/'completion.jsonl').open('a') as f:f.write(json.dumps(record)+'\n')
 latest[key]=record

def audit(prefix):
 key=next(k for k in prior if k.startswith(prefix))
 return '../full-catalogue-v4/Demuxe_All_Items_Screening_v4/'+prior[key]['evidence'][0]['path']
put('R027.','PURSUE', ['../local-screening/runs/module-maintained-pairs-01/summary.json',audit('R027.')], 'Verified local initial startup comparison remains sufficient to justify follow-up: reported 14.10% saving, 95% interval 9.89-18.39% crosses the original 10% gate. Do not repeat this benchmark merely for catalogue closure; cache identity/cancellation and production ownership remain later qualification.', 'IMPORTED_LOCAL_EVIDENCE')
policy=json.loads((root/'remux-policies/result.json').read_text());assert all(x.get('passed') for x in policy['cases'])
a={x['mode']:x for x in policy['cases']};b=a['baseline'];c=a['adaptive-read']
put('R003.','PURSUE','remux-policies/result.json',f"Actual remux read-window candidate reduced requests {b['requestsBeforeAdverse']} to {c['requestsBeforeAdverse']} while fetched bytes changed {b['bytesBeforeAdverse']} to {c['bytesBeforeAdverse']}. Source identity replacement rejects, decoded-frame progress and distant seek pass, workers close. Worth a latency/abandoned-byte tradeoff study; this is not boundary-indexed coalescing or a CPU benchmark.",'REAL_PATH_SCREEN')
put('R026.','PURSUE','remux-policies/result.json',f"Paused pump callbacks changed from {b['idleTicks']} to {a['idle-deadline']['idleTicks']} over the same 1.2s observation. Event wakes resume playback/seek, changed source rejects, and cleanup passes. Worth integrating this one-owner timer policy behind lifecycle checks, not replacing every scheduler.",'REAL_PATH_SCREEN')
put('R049.','PURSUE','remux-policies/result.json',f"At 0.5x startup, peak buffered media changed {b['paused']['stats']['peakBufferedSeconds']}s to {a['rate-aware']['paused']['stats']['peakBufferedSeconds']}s, fetched bytes {b['paused']['source']['fetchedBytes']} to {a['rate-aware']['paused']['source']['fetchedBytes']}. Actual 4x after seek is explicitly asserted; frame progress, source replacement rejection and worker cleanup pass. Worth a bounded rate-aware preparation policy; no generalized high-speed improvement claimed.",'REAL_PATH_SCREEN')
put('R100.','PURSUE',['frame-boundaries/result.json','r332/result.json'],'Whole-owned packet transfer detaches input, preserves chunk bytes and matches independent decoded I420. Shared heaps and oversized subviews reject at the candidate ownership guard. Normal maintained VP9 path already has zero owned packet bytes, so pursue only measured fallback/prefix branches, not global copying changes.')
put('R124.copy-a-frame','STOP_PROFILE','frame-boundaries/result.json','Copying one decoded frame to owned I420 preserves redraw after decoder closure, at 23040 additional copied bytes for this tiny frame. Existing held-frame ownership is bounded and no decoder surface-pressure evidence exists. Do not add routine copies without a trace showing blocked decoder surfaces.')
put('R008.','PURSUE','frame-boundaries/result.json','Existing retained presenter produces exact independently indexed 90-degree pixel rotation; unchanged orientation fails the pixel oracle. Pursue a distinct explicitly display-only operation API. Software filter semantics, subtitle/pointer geometry, HDR and arbitrary transforms are not qualified.')
put('R025.','STOP_PROFILE','frame-boundaries/result.json','The current legacy generated-track sink accepts three delayed writes and presents red/green/blue in order, with clean close. No replacement advantage over existing canvas presentation or complete A/V clock was demonstrated. Keep as a destination-specific option only if a MediaStream consumer is required.')
put('R131.global-mp4','PURSUE',['remote-index/result.json','remote-index/identity.json'],'Same-size same-packet indexed and unindexed variants reach identical target pixel hashes at 20s. Global index reduces this bounded native request trace from 6656858 to 6296410 bytes. Benefit is modest on this 26-second local fixture; pursue asset-side metadata only with real remote byte/latency exposure.')
put('R141.no-index','STOP_PROFILE',['remote-index/result.json','remote-index/identity.json'],'Removing only the random-access trailer after sidx removal adds no requests or bytes in this tested native seek: both fetch 6656858 bytes and the same target picture. Do not build a trailer-specific optimization from this profile; reopen a longer/costlier trace.')
put('R066.','STOP_PROFILE','remote-index/result.json','Moving this indexed native target seek from loadeddata to loadedmetadata preserves target picture but fetches the same 6296410 bytes and 97 responses; zero-start control passes. No byte-work opportunity demonstrated by this variant; single-run timing differences are not evidence of speedup.')
put('R134.complete-sample','STOP_PROFILE','webm-boundaries/result.json','For this actual A/V fMP4, neither complete first video sample nor 37-byte-truncated cut exposes a buffered range or early frame; both complete correctly after remaining data arrives. A complete video sample alone is insufficient for early muxed A/V output. No partial-delivery optimization justified on this fixture.')
put('R112.','ALREADY_IMPLEMENTED',['webm-boundaries/result.json','webm-boundaries/metadata.json'],'Maintained VP9/Opus output already contains video DefaultDuration. Its first block is audio and gives no early frame with or without video duration metadata; do not infer an A/V timing benefit from video-only VP8. Retain truthful duration signaling; no missing metadata fix is needed in this output profile.')
put('R125.webm-defaultduration','PURSUE_AS_REGRESSION_TEST','webm-boundaries/result.json','Truthful 100ms VP8 DefaultDuration yields one early frame and [0,0.1] range from the first block. Replacing only this metadata with same-size Void yields neither until remaining bytes arrive. Worth retaining as parser-availability regression coverage; does not justify inventing VFR durations or claim a missing maintained mux feature.')
put('R110.','ALREADY_IMPLEMENTED',['webm-boundaries/lacing-result.json','webm-boundaries/maintained-lace-result.json'],'Chrome rejects Xiph-laced Opus; current actual Wasm remux emits a playable representation with all 101 packet payloads, exact decoded PCM and 648-sample final trim preserved. Seek and cleanup pass. Preserve this existing normalization and add regression coverage; no new unlacing subsystem needed for this profile.','REAL_PATH_SCREEN')
put('R158.','PURSUE_AS_TEST_TOOL',['webm-boundaries/lacing-result.json','webm-boundaries/lace-identity.json','webm-boundaries/one-lace-identity.json'],'Reducing 49 Xiph lace groups to one retains the identical Chrome CHUNK_DEMUXER_ERROR_APPEND_FAILED / Lacing 1 unsupported predicate; unlaced control plays to EOF with 880Hz audio. Independent packet hashes and PTS match across variants. Worth a structure-aware failure reducer; this controlled fixture reduction is not a generic reducer implementation.')
put('R010.','HOLD_ENV','r10/result.json','Actual finite Float32 WAV reaches EOF and preserves 1.25 sample headroom in direct audio, despite empty canPlayType hints. All four exact tested PCM/WAV streaming MIME queries reject MSE. No unified native streaming A/V float destination established; hold the streaming adapter, not float audio generally.','PREREQUISITE_PROBE')
put('R021.','DEFER_SETUP',['r21/result.json',audit('R021.')],'Actual libass worker initialization cannot import /web/engine-ass/subtitles.mjs; no compiled subtitle .mjs/.wasm assets were found under web/build. Tile-cache candidate did not run. Build the optional pinned subtitle module before measuring repeat tiles; keep exact epoch/color/geometry/byte keys and current unchanged-render shortcut.','ENVIRONMENT_BLOCKER')
put('R022.','DEFER_SETUP',['r21/result.json',audit('R022.')],'The intended ASS-bearing owner lacks its compiled subtitle runtime locally. The component also binds document listeners while player disconnection destroys its owner, so generic popup success would not validate the requested move. Defer the owner-transfer/restore test until that shared subtitle setup exists; no negative Document PiP API verdict.','SOURCE_REVIEW')
put('R169.','HOLD_ENV',audit('R169.'),'Current execution is headless Chrome. Logical frame scheduling and pixel oracles cannot establish physical display cadence or actual compositor presentation opportunities. Keep the cadence idea pending a fixed-display observation; do not call requestAnimationFrame timing a hardware/display result.','SOURCE_REVIEW')
put('R014.','STOP_PROFILE',audit('R014.'),'Current AO explicitly negotiates browser context rate and fixed ring transport; no duplicate resampling stage or oversized-work regression was identified in these owners. Retain required source-to-context conversion and current batching. Reopen only with a rate/occupancy trace demonstrating avoidable conversion or retained work; physical device conversion remains unobserved.','SOURCE_REVIEW')
put('R013.','PURSUE_DESIGN',[audit('R013.'),'r59/result.json','r59/identity.json'],'Explicit disabled-track intent has a concrete owner gap: current Native audio=no only mutes, while negative remux selection means automatic. Selected-track metadata experiment establishes packet-preserving exclusion is feasible, but no no-audio remux sentinel was implemented. Worth a separate explicit disable/re-enable contract; ordinary mute must keep audio prepared.','SOURCE_REVIEW')
put('R192.','PURSUE_AS_TEST_TOOL',['r332/result.json','r57/result.json','r95/result.json','r41/result.json'],'Current campaign oracles reject missing hidden picture dependencies, deliberate channel loss and doubled gain, and check cue timing. These concrete failures justify identity-bearing witnesses as test infrastructure. A single unified per-epoch video/channel/audio-shift witness is still future implementation, not claimed executed here.','EVIDENCE_SYNTHESIS')
put('R267.','PURSUE_DIAGNOSTICS',['remux-policies/result.json',audit('R267.')],'Policy probes separate fetched bytes, request counts, paused wakeups and buffer depth, preventing a request-count reduction from masquerading as a CPU/latency win. Stage-specific deadline slack is still absent. Worth adding bounded observation before further batching optimization; no injected stage-delay experiment or proven missed deadline claimed.','EVIDENCE_SYNTHESIS')
put('R054.','DEFER_SETUP',['continuity/maintained-webm-result.json','webm-boundaries/metadata.json',audit('R054.')],'Actual two-second VP9/Opus output releases two roughly one-second clusters and retains all packets/trim. It does not expose an expensive long-GOP withholding case. A cluster-policy rebuild and representative long-GOP trace are needed before choosing smaller clusters; no negative policy experiment was run.','REAL_PATH_OBSERVATION')
put('R240.vp9-webm','DEFER_SETUP',['continuity/maintained-webm-result.json','webm-boundaries/metadata.json',audit('R240.vp9-webm')],'Current captured VP9 output already releases two small clusters with exact packet identity. No measured withholding benefit supports structural cluster surgery on this fixture. Defer a mux-policy variant until a long-cluster trace shows avoidable delay; splitting cannot create keyframes.','REAL_PATH_OBSERVATION')
put('R321.range-fetch','DEFER_SETUP',[audit('R321.range-fetch'),'webm-boundaries/metadata.json'],'Current small-cluster fixture has no expensive prefix worth bypassing. The current reader already starts misses at requested offsets; demonstrating additional value needs an exact large-Cluster CueRelativePosition seek trace and dependent-frame control. Defer that fixture/index setup; do not treat unknown opportunity as a failed block-relative seek.','SOURCE_REVIEW')
put('R071.','DEFER_SETUP',audit('R071.'),'No new matched Wasm compression-level experiment was run. Historical host level0 trades more bytes for little CPU saving and does not match maintained frame_size, so it cannot select the production level. Defer until preparation CPU is an actual bottleneck and level0/5 can be compared at identical frame duration including browser decode and bytes.','SOURCE_REVIEW')
put('R225.h-264-self','PURSUE','r225/result.json','Generated Annex-B SPS/PPS/IDR suffix decoded by host FFmpeg 8.1.2 yields the exact 48-picture suffix of the 72-frame reference. Missing configuration and dependent start fail. This host oracle is not execution of pinned FFmpeg 7.1.1; browser/TS scanning cost remains unmeasured.')

# Retain prior individual decisions, explicitly labeled as reuse rather than new experiments.
for key,d in prior.items():
 if key in latest:continue
 assert d['decision']!='ADVANCE_CONFIRMATION',key
 paths=['../full-catalogue-v4/Demuxe_All_Items_Screening_v4/'+e['path'] for e in d['evidence']]
 assert all((root/p).is_file() for p in paths),key
 record=dict(key=key,state=d['decision'],evidence=paths,reason=d['reason'],evidence_level=d['evidence_level'],carried_forward=True,next_test=d.get('next_test'),reopen_condition=d.get('reopen_condition'),recorded_at_utc=datetime.datetime.now(datetime.timezone.utc).isoformat())
 with (root/'completion.jsonl').open('a') as f:f.write(json.dumps(record)+'\n')
 latest[key]=record
assert set(latest)==set(prior)
print('All',len(latest),'stable keys have endpoint decisions; blockers are not experiments.')
